!function(e){function p(p){for(var a,i,n=p[0],o=p[1],m=p[2],f=0,c=[];f<n.length;f++)i=n[f],Object.prototype.hasOwnProperty.call(t,i)&&t[i]&&c.push(t[i][0]),t[i]=0;for(a in o)Object.prototype.hasOwnProperty.call(o,a)&&(e[a]=o[a]);for(s&&s(p);c.length;)c.shift()();return d.push.apply(d,m||[]),r()}function r(){for(var e,p=0;p<d.length;p++){for(var r,i=d[p],n=!0,o=1;o<i.length;o++)r=i[o],0!==t[r]&&(n=!1);n&&(d.splice(p--,1),e=a(a.s=i[0]))}return e}function a(p){if(i[p])return i[p].exports;var r=i[p]={i:p,l:!1,exports:{}};return e[p].call(r.exports,r,r.exports,a),r.l=!0,r.exports}var i={},t={106:0},d=[];a.m=e,a.c=i,a.d=function(e,p,r){a.o(e,p)||Object.defineProperty(e,p,{enumerable:!0,get:r})},a.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},a.t=function(e,p){if(1&p&&(e=a(e)),8&p)return e;if(4&p&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(a.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&p&&"string"!=typeof e)for(var i in e)a.d(r,i,function(p){return e[p]}.bind(null,i));return r},a.n=function(e){var p=e&&e.__esModule?function(){return e.default}:function(){return e};return a.d(p,"a",p),p},a.o=function(e,p){return Object.prototype.hasOwnProperty.call(e,p)},a.p="";var n=window.webpackJsonp=window.webpackJsonp||[],o=n.push.bind(n);n.push=p,n=n.slice();for(var m=0;m<n.length;m++)p(n[m]);var s=o;d.push([138,0]),r()}({138:function(e,p,r){"use strict";r.r(p);var a=r(0);Object(a.a)("de","army",r(139),r(1))},139:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"轮式装甲车","link":"de_army#de_army_wav"}],"model":"Sdkfz系列4轮装甲通讯车","description":"<p>二战前，德军已深知战场上通讯的重要性，因此在一战后即开始了战场通讯车的研制，由于“凡尔赛条约”的限制，德军开始只能用轮式装甲车改装为通讯装甲车，而4轮装甲通讯车就是德军在二战前最早改装的战场通讯车。被改装为通讯车的4轮装甲通讯车有多种型号，最早有Sdkfz 14，陆续有P204、Sdkfz 223、Sdkfz 260和Sdkfz 261等，这些车都装备有功率较大的无线电台和框形或杆形天线，除担负战场侦察与通讯任务外，也担负部队与空军飞机的通讯联络任务。</p><p>在4轮装甲通讯车中，Sdkfz 223型是生产数量最多，功能也较突出的一种，Sdkfz 223是以Sdkfz 221/222型的车体为基础，为了轻便，改用MG34机枪替代Sdkfz 222型侦察车的机关炮，加装了大功率无线电台与框形天线，成为具备有一定战斗力、机动性也较强的通讯装甲车。二战早期，这些4轮通讯车跟随德军装甲部队战斗在各战场上，有些还一直坚持到二战后期。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_wav223s_11.jpg","description":"<h6>Sdkfz 223型4轮装甲通讯车</h6><p></p><p>技术数据：</p><p>车长：4.83米，车宽：1.99米，车高：1.78米；战斗全重：4.4吨；乘员：3人。</p><p>发动机功率：75马力，最高车速：85千米/小时，最大行程：310千米。</p><p>装甲厚度：5.0～8.0毫米（后期30毫米）。</p><p>武器配备：一挺MG 34型7.92mm机枪。</p>","caption":""},{"image":"imgs/de/army/de_army_wav223s_12.jpg","description":"<p>Sdkfz 223型4轮装甲通讯车是在Sdkfz 222型4轮装甲侦察车基础上改装的通讯车，除装有Sdkfz 222型原有的电台外，还加装了一台FuG.10SE.30型大功率电台，并在车外安装有可收放的框形天线；注意该型车的驾驶室有2个观察窗口。</p><p>Sdkfz 223型4轮装甲通讯车从1938年开始装备德军侦察部队，替代已经落后的Sdkfz 14装甲通讯车，1935年至1944年间，共生产了550辆。</p><p>图A：展开框形天线，车内电台通过车外的框形天线作远距离无线通讯；</p><p>图B：向后放下框形天线，以免行军途中被障碍物破坏。</p>","caption":""},{"image":"{{text}}Sdkfz 260型4轮装甲通讯车侧视图{{image}}imgs/de/army/de_army_wav223s_13.jpg{{text}}Sdkfz 261型4轮装甲通讯车侧视图{{image}}imgs/de/army/de_army_wav223s_14.jpg","description":"<h6>Sdkfz 260/261型4轮装甲通讯车</h6><p>Sdkfz 260型与Sdkfz 261型4轮装甲通讯车都是使用Sdkfz 221/222型4轮装甲车的底盘改装（注意：该型车驾驶室只有一个窗口，这是与223外形的明显区别）。从1940年1943年两者一共生产了493辆，全部配备给德军部队的侦察营，参战直到二战后期。</p><p></p><p>技术数据：</p><p>车长：4.83米，车宽：1.99米，车高：1.78米；战斗全重：4.3吨。</p><p>发动机功率：90马力，最高车速：85千米/小时，最大行程：310千米。</p><p>通讯设备：除一台小功率电台外，Sdkfz 260型还加装了一台FuG 7大功率无线电台，车外天线一般采用是长杆天线；Sdkfz 261型则加装了一台FuG 12大功率电台，车外天线一般采用框形天线（但也有部分车同时安装两种天线）。</p>","caption":""},{"image":"imgs/de/army/de_army_wav223s_15.jpg","description":"<h6>Sdkfz 14型4轮装甲通讯车</h6><p>Sdkfz 14 型4轮装甲通讯车是德军最早研发的Sdkfz 13 型4轮装甲侦察车的变形车，两者一共生产了147辆，但该车越野能力较差，装甲薄弱，仅仅参加过二战早期的几场战斗，很快就被德军淘汰。</p><p></p><p>技术数据：</p><p>车长：4.2米，车宽：1.7米，车高：1.5米；战斗全重：2.2吨；乘员：2人。</p><p>发动机功率：60马力，最高车速：60千米/小时，最大行程：240千米。</p><p>装甲厚度：8.0毫米。</p><p>武器配备：无。</p>","caption":""}],"part2title":"战场上的Sdkfz系列4轮装甲通讯车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_wav223s_21.jpg","description":"1940年5月，西线法国战场，隶属德军第2装甲师第5侦察营的一辆Sdkfz 223型4轮装甲通讯车。","caption":""},{"image":"imgs/de/army/de_army_wav223s_22.jpg","description":"1941年5月，北非战场利比亚地区，隶属德军第5轻装师第3侦察营的一辆Sdkfz 223型4轮装甲通讯车。","caption":""},{"image":"imgs/de/army/de_army_wav223s_23.jpg","description":"1941年7月，东线苏联战场，隶属德国武装党卫军某装甲师的一辆编号为“SS-68951”的Sdkfz 223型4轮装甲通讯车。","caption":""},{"image":"imgs/de/army/de_army_wav223s_24.jpg","description":"1943年7月，东线苏联战场库尔斯克地区，隶属德军653重装甲歼击营的一辆Sdkfz 260型4轮装甲通讯车。","caption":""},{"image":"imgs/de/army/de_army_wav223s_25.jpg","description":"一辆德军Sdkfz 223型4轮装甲通讯车在树林中作战斗状态前进，这型通讯车除在前线作侦察情况通讯外，还担负着与德国空军的联络任务。","caption":""},{"image":"imgs/de/army/de_army_wav223s_26.jpg","description":"1939年10月，德军一装甲先头部队经过德国一城镇，车队中最前面是一辆Sdkfz 223型4轮装甲通讯车，由于是行军途中，Sdkfz 223的框形天线已经放下。","caption":""},{"image":"imgs/de/army/de_army_wav223s_27.jpg","description":"1940年西线法国战场，一辆Sdkfz 223型4轮装甲通讯车与一辆Sdkfz 222型4轮装甲侦察车一起执行任务，行进中的Sdkfz 223的框形天线已经放下。","caption":""},{"image":"imgs/de/army/de_army_wav223s_28.jpg","description":"1941年巴尔干半岛，正在向前线进发的德国武装党卫军第1“阿道夫·希特勒警卫旗队”侦察部队，前面一辆是233一辆Sdkfz 232型8轮装甲通讯车，后面紧跟着一辆Sdkfz 223型4轮装甲通讯车。","caption":""},{"image":"imgs/de/army/de_army_wav223s_29.jpg","description":"1941年～1942年，东线苏联战场，一辆德军Sdkfz 223型4轮装甲通讯车正在战火漫天的战场中，由于要在前线担任侦察任务，而这些装甲通讯车装甲防护又弱，因此很容易受到攻击而损毁。","caption":""},{"image":"imgs/de/army/de_army_wav223s_30.jpg","description":"1941年，西线法国战场，负责支援德军第7装甲师的一辆德国空军部队Sdkfz 223型4轮装甲通讯车正在为德军飞机与部队作通讯联络。","caption":""},{"image":"imgs/de/army/de_army_wav223s_31.jpg","description":"1941年～1942年，东线苏联战场，一辆德军Sdkfz 223型4轮装甲通讯车正在乡村路上行进。注意该车同时装有框形天线和杆形天线，为了提高远距离通讯能力，框形天线安装位置较高。","caption":""},{"image":"imgs/de/army/de_army_wav223s_32.jpg","description":"1941年，东线苏联战场，在草原上行进的德军“大德意志”装甲师“GD”摩托车步枪营侦察部队，左后面一辆是Sdkfz 223型4轮装甲通讯车（驾驶室开有二个窗口），前面一辆车顶上卷有蓬布应是Sdkfz 261型4轮装甲通讯车（驾驶室开有一个窗口）。","caption":""},{"image":"imgs/de/army/de_army_wav223s_33.jpg","description":"1937年德国本土上的一辆Sdkfz 14型4轮装甲通讯车。由于是用早期的Sdkfz 13型4轮装甲车改装，因此车型小、越野能力与装甲防护都较差，因此二战开始后很快就被Sdkfz 223型4轮装甲通讯车所替代。","caption":""}]}')}});